        ipv6 = rbuf->pkt;
        assert(ipv6 != NULL);
        if ((ipv6->size < sizeof(ipv6_hdr_t)) &&
            (gnrc_pktbuf_realloc_data(ipv6, sizeof(ipv6_hdr_t)) != 0)) {
            DEBUG("6lo iphc: no space to decompress IPHC\n");
            _recv_error_release(sixlo, ipv6, rbuf);
            return;
        }
