Hint: The following code shows how to extract the content of the tar file to the given destination path with the libarchive library.

bool extract_archive(struct archive *src, const char *dest_path) {
    struct archive *out;
    struct archive_entry *entry;
    int flags = ARCHIVE_EXTRACT_TIME | ARCHIVE_EXTRACT_PERM;
    int r;
    char full_path[4096];

    // Initialize the archive writer
    out = archive_write_disk_new();
    if (!out) {
        return false;
    }
    archive_write_disk_set_options(out, flags);

    // Read and extract each entry
    while ((r = archive_read_next_header(src, &entry)) == ARCHIVE_OK) {
        // Create full path
        snprintf(full_path, sizeof(full_path), "%s/%s",
                dest_path, archive_entry_pathname(entry));
        archive_entry_set_pathname(entry, full_path);

        // Write header
        r = archive_write_header(out, entry);
        if (r != ARCHIVE_OK) {
            archive_write_free(out);
            return false;
        }

        // Copy data
        const void *buff;
        size_t size;
        la_int64_t offset;
        while ((r = archive_read_data_block(src, &buff, &size, &offset)) == ARCHIVE_OK) {
            if (archive_write_data_block(out, buff, size, offset) != ARCHIVE_OK) {
                archive_write_free(out);
                return false;
            }
        }
        if (r != ARCHIVE_EOF) {
            archive_write_free(out);
            return false;
        }
    }

    archive_write_free(out);
    return r == ARCHIVE_EOF ? true : false;
}


@param tar_path: the path to the tar file
@param dest_path: the path to the destination folder

@return true if the extraction is successful; otherwise, false
*/
bool extract_tar_to_path(const char *tar_path, const char *dest_path) {
    // BEGIN SOLUTION
    struct archive *a;
    struct archive *ext;
    struct archive_entry *entry;
    int flags = ARCHIVE_EXTRACT_TIME | ARCHIVE_EXTRACT_PERM;
    int r;

    // Check if input paths are NULL
    if (!tar_path || !dest_path) {
        return false;
    }

    // Initialize archive object for reading
    a = archive_read_new();
    if (!a) {
        return false;
    }

    // Support common tar formats
    archive_read_support_filter_all(a);
    archive_read_support_format_all(a);

    // Initialize archive object for writing
    ext = archive_write_disk_new();
    if (!ext) {
        archive_read_free(a);
        return false;
    }

    archive_write_disk_set_options(ext, flags);
    archive_write_disk_set_standard_lookup(ext);

    // Open tar file
    if (archive_read_open_filename(a, tar_path, 10240) != ARCHIVE_OK) {
        archive_read_free(a);
        archive_write_free(ext);
        return false;
    }

    // First pass: check all paths
    while (archive_read_next_header(a, &entry) == ARCHIVE_OK) {
        const char *current_file = archive_entry_pathname(entry);
        if (!is_path_safe(current_file)) {
            archive_read_free(a);
            archive_write_free(ext);
            return false;
        }
        archive_read_data_skip(a);
    }

    // Reset archive for second pass
    archive_read_free(a);
    a = archive_read_new();
    archive_read_support_filter_all(a);
    archive_read_support_format_all(a);

    if (archive_read_open_filename(a, tar_path, 10240) != ARCHIVE_OK) {
        archive_read_free(a);
        archive_write_free(ext);
        return false;
    }

    // Second pass: extract files
    while ((r = archive_read_next_header(a, &entry)) == ARCHIVE_OK) {
        const char *current_file = archive_entry_pathname(entry);
        char full_path[PATH_MAX];
        snprintf(full_path, PATH_MAX, "%s/%s", dest_path, current_file);

        archive_entry_set_pathname(entry, full_path);

        r = archive_write_header(ext, entry);
        if (r != ARCHIVE_OK) {
            archive_read_free(a);
            archive_write_free(ext);
            return false;
        }

        // Copy data
        const void *buff;
        size_t size;
        la_int64_t offset;

        while (archive_read_data_block(a, &buff, &size, &offset) == ARCHIVE_OK) {
            if (archive_write_data_block(ext, buff, size, offset) != ARCHIVE_OK) {
                archive_read_free(a);
                archive_write_free(ext);
                return false;
            }
        }
    }

    archive_read_free(a);
    archive_write_free(ext);

    return r == ARCHIVE_EOF ? true : false;
}

int is_path_safe(const char *path) {
    if (path[0] == '/') {  // Check for absolute path
        return false;
    }

    char *path_copy = strdup(path);
    char *token = strtok(path_copy, "/");

    while (token != NULL) {
        if (strcmp(token, "..") == 0) {
            free(path_copy);
            return false;
        }
        token = strtok(NULL, "/");
    }

    free(path_copy);
    return true;
}

